def quad_stats(g):
 n=len(g); q=n//2; mid=n//2
 quads=[(0,0,False),(0,n-q,True),(n-q,0,True),(n-q,n-q,False)]
 for top,left,anti in quads:
  colors={g[r][c] for r in range(top,top+q) for c in range(left,left+q)}-{7}
  print('quad',top,left,colors)
  for col in colors:
   pts={(r-top,c-left) for r in range(top,top+q) for c in range(left,left+q) if g[r][c]==col}
   diag={(i,q-1-i if anti else i) for i in range(q)}
   print(col,len(pts), 'missing',len(diag-pts),'extra',len(pts-diag),'dist',len(diag^pts))
for p in pairs:
 print('\nPAIR');quad_stats(p['input'])
print('\nTEST');quad_stats(test)

